sysauto_script.script:
(function() {
    try {
        var importer = new MovieImporter();
        var batchSize = parseInt(gs.getProperty("x_1080820_mvx.tmdb.page_size", 20), 10);
        if (isNaN(batchSize)) batchSize = 20;


        // Nazov System Property, ktora bude sluzit ako bookmark
        var propertyName = "x_1080820_mvx.last_processed_created";
        var lastProcessed = gs.getProperty(propertyName);	        // Skontroluj, ci property existuje; ak nie, vytvor ju s prazdnou hodnotou

        if (lastProcessed === null) {
            gs.setProperty(propertyName, "");
            lastProcessed = "";
            gs.info("[ScheduledJob] System property '" + propertyName + "' created.");
        }

        var gr = new GlideRecord("x_1080820_mvx_movie");
        if (lastProcessed) {
            gr.addQuery("sys_created_on", ">", lastProcessed);
        }
        gr.orderBy("sys_created_on");
        gr.setLimit(batchSize);
        gr.query();

        var processedCount = 0;
        var newLastProcessed = lastProcessed;

		while (gr.next()) {
            var tmdbId = gr.getValue("tmdb_id");
            if (tmdbId) {
                gs.info("[ScheduledJob] Updating movie: " + gr.getValue("title") + " (TMDb ID: " + tmdbId + ")");
                importer.importMovie(tmdbId);
            }
            newLastProcessed = gr.getValue("sys_created_on");
            processedCount++;
        }

        if (processedCount > 0) {
            gs.setProperty(propertyName, newLastProcessed);
            gs.info("[ScheduledJob] Processed " + processedCount + " movies. Last created_on: " + newLastProcessed);
        } else {
            gs.info("[ScheduledJob] No more records to process. Resetting bookmark.");
            gs.setProperty(propertyName, "");
        }

    } catch (e) {
        gs.error("[ScheduledJob] Failed: " + e.message);
    }
})();
